const failing = String((($('Load private config').all().find((i) => i.json.key === 'test_fail') || {}).json || {}).value || '').split(',').map((s) => s.trim());
if (failing.includes("Gmail \u00b7 list last 24h")) return [{ json: { error: { message: 'Request failed with status code 401', httpCode: '401' } } }];
// TEST ONLY. Stands in for the Gmail list call: same shape as users.messages.list.
return [{ json: { messages: ['fixture-m1', 'fixture-m2', 'fixture-m3', 'fixture-m4', 'fixture-m5'].map((id) => ({ id, threadId: id })), resultSizeEstimate: 5 } }];

// One item per mail ID from the list call. No mail in 24 hours: nothing to read, the branch ends here.
const list = $input.first().json;
if (list.error) return [];
return (list.messages || []).slice(0, 40).map((m) => ({ json: { id: m.id } }));

const failing = String((($('Load private config').all().find((i) => i.json.key === 'test_fail') || {}).json || {}).value || '').split(',').map((s) => s.trim());
if (failing.includes("Gmail \u00b7 read headers")) return [{ json: { error: { message: 'Request failed with status code 401', httpCode: '401' } } }];
// TEST ONLY. Stands in for the Gmail read call: same shape as users.messages.get with format=metadata.
const mails = {
  'fixture-m1': ['EPITA Scolarité <scolarite@epita.fr>', 'Exam timetable: confirm your slot by Fri 6 Nov', 'Please confirm your exam slot on the intranet before Friday 6 November, 18:00.', 'CATEGORY_PERSONAL'],
  'fixture-m2': ['"Automation with n8n" <teacher@example.edu>', 'Defense day: book your 12-minute slot', 'Book a slot for the 13 November defense in the shared sheet.', 'CATEGORY_PERSONAL'],
  'fixture-m3': ['GitHub <noreply@github.com>', 'ThariqS/ai-newtab published a new release', 'Release v0.4.0 is out.', 'CATEGORY_UPDATES'],
  'fixture-m4': ['Fnac <news@fnac.com>', 'Black Friday early access', 'Up to 40% off.', 'CATEGORY_PROMOTIONS'],
  // A one-time code: it must never reach the agent, the EDITION or the cache (the code here is made up).
  'fixture-m5': ['Uber <noreply@uber.com>', 'Ne pas partager : 482913', 'Votre code Uber est 482913. Ne le partagez avec personne.', 'CATEGORY_UPDATES'],
};
return $input.all().map((i) => {
  const [from, subject, snippet, category] = mails[i.json.id];
  return { json: { id: i.json.id, threadId: i.json.id, labelIds: ['INBOX', category], snippet,
    payload: { headers: [{ name: 'From', value: from }, { name: 'Subject', value: subject }] } } };
});

const failing = String((($('Load private config').all().find((i) => i.json.key === 'test_fail') || {}).json || {}).value || '').split(',').map((s) => s.trim());
if (failing.includes("IBKR \u00b7 request statement")) return [{ json: { error: { message: 'Request failed with status code 401', httpCode: '401' } } }];
// TEST ONLY. Stands in for IBKR SendRequest: a reference code for the report.
return [{ json: { data: '<FlexStatementResponse timestamp="31 October, 2026 08:00 AM EDT"><Status>Success</Status><ReferenceCode>1234567890</ReferenceCode><Url>https://ndcdyn.interactivebrokers.com/AccountManagement/FlexWebService/GetStatement</Url></FlexStatementResponse>' } }];

const failing = String((($('Load private config').all().find((i) => i.json.key === 'test_fail') || {}).json || {}).value || '').split(',').map((s) => s.trim());
if (failing.includes("IBKR \u00b7 get statement")) return [{ json: { error: { message: 'Request failed with status code 401', httpCode: '401' } } }];
// TEST ONLY. Stands in for the first GetStatement: the report is still being generated (code 1019).
return [{ json: { data: '<FlexStatementResponse timestamp="31 October, 2026 08:00 AM EDT"><Status>Warn</Status><ErrorCode>1019</ErrorCode><ErrorMessage>Statement generation in progress. Please try again shortly.</ErrorMessage></FlexStatementResponse>' } }];

const failing = String((($('Load private config').all().find((i) => i.json.key === 'test_fail') || {}).json || {}).value || '').split(',').map((s) => s.trim());
if (failing.includes("IBKR \u00b7 get statement (retry)")) return [{ json: { error: { message: 'Request failed with status code 401', httpCode: '401' } } }];
// TEST ONLY. Stands in for the second GetStatement: open positions, including quantity and value
// attributes, so the test shows that "Watchlist codes (IBKR counted)" drops them.
const row = (s, w, qty, value) => `<OpenPosition accountId="U0000000" currency="USD" assetCategory="STK" symbol="${s}" description="${s}" position="${qty}" markPrice="1" positionValue="${value}" percentOfNAV="${w}" levelOfDetail="SUMMARY" />`;
return [{ json: { data: '<FlexQueryResponse queryName="daily-page-positions" type="AF"><FlexStatements count="1"><FlexStatement accountId="U0000000"><OpenPositions>' +
  [row('AAPL', 31.5, 40, 9200), row('NVDA', 24.2, 50, 7100), row('QQQ', 22.8, 12, 6700), row('TSLA', 12.1, 15, 3550)].join('') +
  '</OpenPositions></FlexStatement></FlexStatements></FlexQueryResponse>' } }];

// The market board shows the 8 watchlist codes (the user's choice, 11-01). The IBKR statement is still read,
// but its positions are only counted: no code, weight, quantity or amount leaves this node,
// so nothing from the account is cached, logged, shown or sent to the model.
const watch = $('My watchlist').first().json;
const ran = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
const ibkr = { connected: ran('IBKR · request statement'), positions: null, error: null };
if (ibkr.connected) {
  const text = (n) => String(($(n).first().json || {}).data || '');
  const statement = text(ran('IBKR · get statement (retry)') ? 'IBKR · get statement (retry)' : 'IBKR · get statement');
  const errorCode = (s) => (s.match(/<ErrorCode>(\d+)<\/ErrorCode>/) || [])[1];
  ibkr.error = errorCode(text('IBKR · request statement')) || errorCode(statement) ||
    (/<FlexQueryResponse/.test(statement) ? null : 'no statement');
  if (!ibkr.error) {
    // A query can list one row per lot as well as the summary; count each code once.
    const codes = new Set();
    for (const m of statement.matchAll(/<OpenPosition\b([^>]*?)\/?>/g)) {
      const a = {};
      for (const x of m[1].matchAll(/(\w+)="([^"]*)"/g)) a[x[1]] = x[2];
      if (a.symbol && (!a.levelOfDetail || a.levelOfDetail === 'SUMMARY')) codes.add(a.symbol);
    }
    ibkr.positions = codes.size;
  }
}
return watch.marketSymbols.slice(0, 8).map((symbol) => ({ json: { symbol, name: (watch.marketNames || {})[symbol] || null, ibkr } }));

const failing = String((($('Load private config').all().find((i) => i.json.key === 'test_fail') || {}).json || {}).value || '').split(',').map((s) => s.trim());
if (failing.includes("Twelve Data \u00b7 daily candles")) return [{ json: { error: { message: 'Request failed with status code 401', httpCode: '401' } } }];
// TEST ONLY. Stands in for Twelve Data time_series: 30 daily candles per code, newest first.
// TSLA closes under its 1-month low and SPCX over its 1-month high, so both texts are tested.
// To rehearse one code failing, put it in the test config table: key test_fail_symbol (Twelve Data's error shape).
const failingSymbols = String((($('Load private config').all().find((i) => i.json.key === 'test_fail_symbol') || {}).json || {}).value || '');
return $input.all().map((i, k) => {
  const symbol = i.json.symbol;
  if (failingSymbols.split(',').map((x) => x.trim()).includes(symbol)) {
    return { json: { code: 404, message: '**symbol** not found: ' + symbol + '. Please specify it correctly', status: 'error' } };
  }
  const base = [690, 345, 520, 280, 205, 615, 400, 135][k % 8];
  const values = Array.from({ length: 30 }, (_, d) => {
    let c = base * (1 + 0.02 * Math.sin((d + k) / 3) - 0.001 * d);
    if (d === 0 && symbol === 'TSLA') c = base * 0.95;
    if (d === 0 && symbol === 'SPCX') c = base * 1.06;
    const day = $now.setZone('Europe/Paris').minus({ days: d + 1 }).toFormat('yyyy-MM-dd');
    return { datetime: day, open: (c * 0.995).toFixed(2), high: (c * 1.01).toFixed(2), low: (c * 0.985).toFixed(2), close: c.toFixed(2), volume: '1000' };
  });
  return { json: { meta: { symbol, interval: '1day' }, values, status: 'ok' } };
});

const failing = String((($('Load private config').all().find((i) => i.json.key === 'test_fail') || {}).json || {}).value || '').split(',').map((s) => s.trim());
if (failing.includes("SerpApi \u00b7 this month")) return [{ json: { error: { message: 'Request failed with status code 401', httpCode: '401' } } }];
// TEST ONLY. Stands in for SerpApi account.json (this call is free).
// To rehearse the quota guard, put a number in the test config table: key test_quota_left.
const set = (($('Load private config').all().find((i) => i.json.key === 'test_quota_left') || {}).json || {}).value;
const left = set != null && set !== '' ? Number(set) : 209;
return [{ json: { this_month_usage: 250 - left, searches_per_month: 250, plan_searches_left: left } }];

// SerpApi's free plan has 250 searches a month. This node decides which searches run now.
// A search made earlier today is never repeated, so a rebuild (for example during the defense) costs 0 searches.
// The order is flights, then Google Shopping, then hotels. A search that would leave fewer than 15 searches
// for later is skipped and its cache is used; the log says so in one line.
const MARGIN = 15;
const ctx = $('Run context').first().json;
const watch = $('My watchlist').first().json;
const t = watch.travel;
const searchedToday = (node) => String(($(node).first().json || {}).fetched_at || '').slice(0, 10) === ctx.date;

const acc = $('SerpApi · this month').first().json || {};
const left = Number.isFinite(acc.plan_searches_left) ? acc.plan_searches_left
  : Number.isFinite(acc.searches_per_month) && Number.isFinite(acc.this_month_usage) ? acc.searches_per_month - acc.this_month_usage : null;

// Hotels change slowly: each city once a week, and again when the hotel filter changes.
const cache = $('Load travel cache').first().json;
const hotels = (cache && cache.payload ? JSON.parse(cache.payload).hotels : null) || {};
const weekAgo = $now.setZone('Europe/Paris').minus({ days: 7 }).toFormat('yyyy-MM-dd');
const hotelRoutes = t.routes
  .filter((r) => !hotels[r.code] || hotels[r.code].searchedOn <= weekAgo || hotels[r.code].filter !== t.hotelFilter.tag)
  .map((r) => ({ city: r.city, code: r.code, out: t.out, back: t.back, day: ctx.date }));

const due = { flights: searchedToday('Load travel cache') ? 0 : t.routes.length,
  shopping: searchedToday('Load shopping cache') ? 0 : watch.deals.filter((d) => d.query).length, hotels: hotelRoutes.length };
// When the account call fails, the count is unknown and the searches run as before.
let budget = left == null ? Infinity : left - MARGIN;
const fits = (n) => {
  if (!n || n > budget) return false;
  budget -= n;
  return true;
};
const flights = fits(due.flights);
const shopping = fits(due.shopping);
const hotelCount = Math.max(0, Math.min(due.hotels, budget));
const skipped = [[!flights && due.flights, ' flight'], [!shopping && due.shopping, ' Google Shopping'], [due.hotels - hotelCount, ' hotel']]
  .filter(([n]) => n > 0).map(([n, what]) => n + what + (n > 1 ? ' searches' : ' search'));
const note = skipped.length ? 'SerpApi quota guard: ' + left + ' searches left this month, kept ' + MARGIN + ' for later; skipped ' +
  skipped.join(', ') + ' (cache used)' : null;
return [{ json: { left, margin: MARGIN, due, flights, shopping, hotels: hotelRoutes.slice(0, hotelCount), note } }];

// One SerpApi flight search per route: 5 a day, about 150 a month on the free plan's 250.
const t = $('My watchlist').first().json.travel;
return t.routes.map((r) => ({ json: { city: r.city, code: r.code, from: t.origin, out: t.out, back: t.back } }));

const failing = String((($('Load private config').all().find((i) => i.json.key === 'test_fail') || {}).json || {}).value || '').split(',').map((s) => s.trim());
if (failing.includes("SerpApi \u00b7 flights")) return [{ json: { error: { message: 'Request failed with status code 401', httpCode: '401' } } }];
// TEST ONLY. Stands in for SerpApi Google Flights: prices and price_insights per route.
const fares = { JFK: 640, ZRH: 210, LHR: 165, HND: 812, TPE: 905 };
return $input.all().map((i) => {
  const fare = fares[i.json.code];
  // Like Google: one fare per Paris day, ending with today (the last point is today's fare).
  const today = DateTime.now().setZone('Europe/Paris').startOf('day');
  const history = Array.from({ length: 10 }, (_, d) => [today.minus({ days: 9 - d }).toSeconds(), d === 9 ? fare : Math.round(fare * (1.12 - d * 0.01))]);
  // Google gives no price_insights for CDG-HND (seen on 11-01), so the test covers that case too.
  const insights = i.json.code === 'HND' ? {} : { price_insights: { lowest_price: fare, price_level: 'typical',
    typical_price_range: [Math.round(fare * 0.9), Math.round(fare * 1.2)], price_history: history } };
  return { json: { best_flights: [{ price: fare }], other_flights: [{ price: fare + 40 }], ...insights } };
});

// One Google Shopping search per watchlist item (2 a day), in France and in French.
const watch = $('My watchlist').first().json;
return watch.deals.filter((d) => d.query).map((d) => ({ json: { label: d.label, q: d.query } }));

const failing = String((($('Load private config').all().find((i) => i.json.key === 'test_fail') || {}).json || {}).value || '').split(',').map((s) => s.trim());
if (failing.includes("SerpApi \u00b7 shopping")) return [{ json: { error: { message: 'Request failed with status code 401', httpCode: '401' } } }];
// TEST ONLY. Stands in for SerpApi Google Shopping (gl=fr, hl=fr), in its shape, with titles seen on 11-01.
// Each list has offers the rules must leave out: no touch screen, M5 Max, 16-inch, used or refurbished,
// women's, Beta LT/SL, another colour ("Black Sapphire" is a blue), and too cheap to be the product.
const offer = (title, price, source, used) => ({ title, extracted_price: price, price: price + ' €', source,
  ...(used ? { second_hand_condition: used } : {}), product_link: 'https://www.google.com/shopping/product/test' });
const lists = {
  'MacBook Pro 14 PROLED': [
    offer('Apple MacBook Pro M5 Pro 14" 24Go/2To Noir', 3449, 'Darty.com'),
    offer('Apple MacBook Pro M5 Pro 14" Argent 24 Go/2 To', 3099, 'Veepee'),
    offer('Apple Pro 14" Écran PROLED XDR 1 To SSD 24 Go RAM Puce M5 Pro CPU 15 cœurs GPU 16 cœurs Noir sidéral MacBook', 3299, 'Apple'),
    offer('Apple Pro 14" Écran PROLED XDR 1 To SSD 24 Go RAM Puce M5 Pro CPU 15 cœurs GPU 16 cœurs Argent MacBook', 3249, 'Boulanger'),
    offer('Apple Pro 14" Écran PROLED XDR 2 To SSD 36 Go RAM Puce M5 Max CPU 18 cœurs GPU 32 cœurs Noir sidéral MacBook', 5199, 'Apple'),
    offer('Apple MacBook Pro 16" Écran PROLED XDR M5 Pro', 3799, 'Fnac'),
    offer('MacBook Pro 14 Écran PROLED XDR M5 Pro - coque de protection', 39, 'Amazon.fr'),
    offer('Apple Pro 14" Écran PROLED XDR M5 Pro MacBook', 2799, 'Back Market', 'reconditionné'),
  ],
  'Beta AR Jacket': [
    offer("Arc'teryx Beta AR Homme Veste", 649.9, 'Snowleader.com'),
    offer("Arc'teryx - BLACK BETA AR JACKET", 650, 'lelabostore.com'),
    offer("Arc'teryx Beta AR Jacket (SS24) Black Sapphire - XXL", 610, 'Geturbrick'),
    offer("Arc'teryx Beta AR Femme Veste", 583.95, 'Bergtopia'),
    offer("Veste Arc'teryx Beta LT Homme Jacket", 500, 'Station-store.com'),
    offer('[S] Arc\'teryx Beta AR Jacket Black', 415.92, 'NaturaBuy', 'occasion'),
    offer("Arc'teryx Beta AR Jacket Men's Black", 620, 'Test Shop'),
    // Under the 520 target, but neither colour nor men's/women's is stated: it must stay "know".
    offer("Arc'teryx Beta AR Jacket", 499, 'Test Outlet'),
  ],
};
return $input.all().map((i) => ({ json: { search_metadata: { status: 'Success' }, shopping_results: lists[i.json.label] || [] } }));

// The cities to search for hotels now: chosen by SerpApi plan (once a week per city, within the monthly quota).
// It also runs when the flights were already searched today.
return $('SerpApi plan').first().json.hotels.map((r) => ({ json: r }));

const failing = String((($('Load private config').all().find((i) => i.json.key === 'test_fail') || {}).json || {}).value || '').split(',').map((s) => s.trim());
if (failing.includes("SerpApi \u00b7 hotels")) return [{ json: { error: { message: 'Request failed with status code 401', httpCode: '401' } } }];
// TEST ONLY. Stands in for SerpApi Google Hotels: hotels with class and rating, plus a cheap "3-star" hostel
// that the hostel rule must leave out. The price used is the median of the rest.
const night = { JFK: 210, ZRH: 160, LHR: 140, HND: 120, TPE: 85 };
return $input.all().map((i) => ({ json: { properties: [
  { type: 'hotel', name: 'Wise Owl Hostels', extracted_hotel_class: 3, overall_rating: 4.5, rate_per_night: { extracted_lowest: 25 } },
  ...[0, 15, 40].map((d, k) => ({ type: 'hotel', name: 'Hotel ' + k, extracted_hotel_class: 4, overall_rating: 4.3, rate_per_night: { extracted_lowest: night[i.json.code] + d } })),
] } }));

// Decide, per source, whether today's data is usable. A failed source falls back to the
// last good copy in source_cache and is marked "stale". Nothing here calls the model.
const ctx = $('Run context').first().json;
const watch = $('My watchlist').first().json;
const cache = {};
for (const item of $('Load source cache').all()) {
  if (item.json.source) cache[item.json.source] = item.json;
}
const cached = (key) => (cache[key] ? JSON.parse(cache[key].payload) : null);
const log = [];
const updates = [];

// A node exists only once its source is connected, so check before reading it.
const ran = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };

// An HTTP or RSS node set to "continue" returns { error } instead of data.
function failure(nodeName) {
  if (!ran(nodeName)) return null;
  const items = $(nodeName).all();
  if (!items.length) return 'no response';
  const e = items[0].json.error;
  if (!e) return null;
  const text = typeof e === 'string' ? e : (e.message || e.description || JSON.stringify(e));
  const code = (e.httpCode || (String(text).match(/[1-5][0-9][0-9]/) || [])[0]);
  return code ? 'HTTP ' + code : String(text).slice(0, 60);
}

function source(key, nodes, read, meta) {
  let failed = nodes.map(failure).filter(Boolean);
  let payload = null;
  if (!failed.length) {
    try { payload = read(); } catch (e) { failed = [String(e.message || e).slice(0, 60)]; }
  }
  if (!failed.length) {
    updates.push({ source: key, fetched_at: ctx.startedAt, payload: JSON.stringify(payload) });
    log.push({ t: ctx.time, msg: meta.short + ': OK' });
    return { payload, status: { ...meta, status: 'ok', detail: meta.describe(payload), code: null, note: null, cachedAt: null, fetched: ctx.time } };
  }
  const code = failed[0];
  log.push({ t: ctx.time, msg: meta.short + ': ' + code + ' after one retry, cache used', bad: true });
  const old = cache[key];
  return {
    payload: old ? JSON.parse(old.payload) : null,
    status: {
      ...meta,
      status: 'stale',
      detail: old ? meta.describe(JSON.parse(old.payload)) : 'No data',
      code,
      note: meta.short + ' returned ' + code + ' twice. ' + (old ? 'Showing the copy from ' + old.fetched_at.slice(0, 16).replace('T', ' ') + '.' : 'No cached copy yet.') + ' The next run retries automatically.',
      cachedAt: old ? old.fetched_at : null,
      fetched: ctx.time,
    },
  };
}

// Zeus runs only when the private config table has a link. Classes for the next 14 days, Paris time.
// A revoked link answers with an error or a login page; both count as a failure here.
const zeus = ran('Zeus · timetable (ICS)') ? source(
  'zeus',
  ['Zeus · timetable (ICS)', 'Read Zeus events'],
  () => {
    const from = $now.setZone('Europe/Paris').startOf('day');
    const until = from.plus({ days: 14 });
    const at = (d) => DateTime.fromISO(new Date(d).toISOString()).setZone('Europe/Paris');
    return (($('Read Zeus events').first().json.data || {}).events || [])
      // Zeus also lists holidays ("Vacances", "Bank Holiday") as events; they are not classes.
      .filter((e) => e.start && !/vacances|holiday|férié/i.test(e.summary || ''))
