  news.push({ title: h.title, url, list: 'hot', heat: h.participantCount || h.sourceCount || 0, hotRank: h.rank, isNew: !seen.has(url) });
}
for (const i of aihot.items) {
  if (!keywordRe.test(i.title + ' ' + i.summary) || byUrl.has(i.url)) continue;
  byUrl.add(i.url);
  news.push({ title: i.title, url: i.url, list: '24h', heat: i.score || 0, summary: i.summary, isNew: !seen.has(i.url) });
}
const quietKeywords = watch.newsKeywords.filter((k) => !news.some((n) => new RegExp(k, 'i').test(n.title + ' ' + (n.summary || ''))));

// The 7-day low (the user's rule, 11-01: every price is compared with the lowest price of the week before).
// It is the lowest logged price of the 7 calendar days before today, by Paris date; today never counts.
const weekAgo = DateTime.fromISO(ctx.date).minus({ days: 7 }).toISODate();
const priceLog = $('Load price log').all().map((i) => i.json).filter((r) => r.day >= weekAgo && r.day < ctx.date);
const logged = (item) => priceLog.filter((r) => r.item === item).sort((a, b) => (a.day < b.day ? -1 : 1)).map((r) => r.price);
const vsLow = (price, low) => {
  if (price == null || low == null) return null;
  const pct = Math.round((Math.abs(price - low) / low) * 1000) / 10;
  return price === low ? 'equal to the low' : pct + (price < low ? ' % below the low' : ' % above the low');
};

// Deals: the cheapest matching item per watchlist entry.
const parsePrice = (t) => {
  if (!t) return null;
  const n = Number(String(t).replace(/[^0-9,.]/g, '').replace(',', '.'));
  return Number.isFinite(n) && n > 0 ? n : null;
};
const deals = [];
const noDeal = [];
// The watchlist's offers come from Dealabs and Google Shopping. An offer counts when its title matches every "must"
// pattern and no "exclude" pattern, it is new (not used or refurbished), and its price is not under minPrice.
// Accessories and refurbished items match product names too; dealExclude leaves them out for every item.
const excludeRe = new RegExp(watch.dealExclude || '^$', 'i');
// Club or subscription prices (for example "[Club+/Infinity]") are not open to everyone.
const memberRe = new RegExp(watch.memberOnly || '^$', 'i');
const shop = (checked.data.shopping || {}).products || {};
for (const w of watch.deals) {
  const must = (w.must || [w.pattern]).map((x) => new RegExp(x, 'i'));
  const own = new RegExp(w.exclude || '^$', 'i');
  const colour = w.colour ? { want: new RegExp(w.colour.want, 'i'), other: new RegExp(w.colour.other, 'i') } : null;
  const fits = (o) => o.price != null && o.price >= (w.minPrice || 0) && !o.used && must.every((re) => re.test(o.title)) &&
    !own.test(o.title) && !excludeRe.test(o.title) && !(colour && colour.other.test(o.title));
  const offers = (checked.data.deals || [])
    .map((d) => ({ title: d.title, merchant: d.merchant, price: parsePrice(d.priceText), link: d.link, from: 'Dealabs' }))
    .concat((shop[w.label] || []).map((r) => ({ ...r, from: 'Google Shopping' })))
    .filter(fits)
    .sort((a, b) => a.price - b.price);
  if (!offers.length) { noDeal.push(w.label); continue; }
  const best = offers[0];
  const memberOnly = memberRe.test(best.title);
  // Only prices open to everyone are logged and count for the low; a member price can still be shown.
  const open = offers.find((m) => !memberRe.test(m.title));
  const before = logged(w.label);
  const low7 = before.length ? Math.min(...before) : null;
  deals.push({ label: w.label, title: best.title, merchant: best.merchant, price: best.price,
    // "from" is where today's lowest public price was found; listPrice is the official price.
    from: (open || best).from, listPrice: w.listPrice || null, target: w.target, underTarget: best.price < w.target, memberOnly,
    publicPrice: open ? open.price : null, publicMerchant: open ? open.merchant : null,
    // A member price is not compared with the low (the low has only public prices); the public price is.
    low7, lowDays: before.length, vsLow7: vsLow(memberOnly ? (open ? open.price : null) : best.price, low7),
    // A title without a colour, or without men's or women's, is kept and marked, never guessed.
    note: [colour && !colour.want.test(best.title) ? 'colour not stated' : null,
      w.gender && !new RegExp(w.gender, 'i').test(best.title) ? "men's or women's not stated" : null].filter(Boolean).join('; ') || null,
    link: best.link });
}

// Codex quota, from AIHOT's reset monitor.
const codexEvents = (aihot.codex && aihot.codex.events) || [];
// The label in brackets is left out when the title already says it ("… 重置卡 (重置卡发放)").
const codexLabel = codexEvents.length ? String(codexEvents[0].displayLabel || codexEvents[0].label || codexEvents[0].status || '') : '';
const codexSame = codexLabel && (codexEvents[0].title.includes(codexLabel) || codexEvents[0].title.includes(codexLabel.slice(0, 3)));
const codex = codexEvents.length
  ? codexEvents[0].title + (codexLabel && !codexSame ? ' (' + codexLabel + ')' : '') + ', ' + String(codexEvents[0].createdAt || '').slice(0, 10) + '.'
  : 'No Codex reset in the last days.';

// Classes: today's list for the page; later days stay in the timetable table for lookup_courses.
const classes = checked.data.zeus;
let courses = null;
if (classes) {
  const later = classes.find((c) => c.day > ctx.date);
  const when = later && DateTime.fromISO(later.start).setZone('Europe/Paris').setLocale('en');
  courses = {
    today: classes.filter((c) => c.day === ctx.date).map((c) => ({ time: c.time, title: c.title, where: c.where })),
    next: later ? when.toFormat(when.diff($now.setZone('Europe/Paris').startOf('day'), 'days').days < 6 ? 'cccc' : 'ccc d LLL') + ', ' + later.time.slice(0, 5) + ': ' + later.title : null,
  };
}

// Mail: newsletters and promotions are only counted. The agent sees sender, subject and a short snippet of the rest.
const mails = checked.data.gmail;
// Mails with a one-time code are never sent to the agent; the page only counts them.
const mail = mails ? mails.filter((m) => !m.bulk && !m.code).slice(0, 20).map(({ id, from, subject, snippet, isNew }) => ({ id, from, subject, snippet, isNew })) : null;
const hiddenMail = mails ? mails.filter((m) => m.bulk && !m.code).length : 0;
const codesHidden = mails ? mails.filter((m) => m.code).length : 0;

// Portfolio: the agent gets codes and percentages only (daily change, weight). Never quantities or amounts.
// The 1-month high and low: the highest and lowest close of the 21 trading days before the last close
// (closes 9 to 29 of 30; the last day is not in it). The page computes the same text from "closes".
const pct1 = (x) => (Math.round(x * 1000) / 10).toFixed(1);
function month(closes) {
  const last = closes[closes.length - 1];
  const before = closes.slice(Math.max(0, closes.length - 22), closes.length - 1);
  if (!before.length) return { high1m: null, low1m: null, vs1m: null };
  const high = Math.max(...before);
  const low = Math.min(...before);
  const vs1m = last < low ? pct1((low - last) / low) + ' % under 1-month low'
    : last > high ? pct1((last - high) / high) + ' % over 1-month high'
    // Inside the range: say which end is nearer.
    : (last - low) / low <= (high - last) / high ? pct1((last - low) / low) + ' % above 1-month low'
    : pct1((high - last) / high) + ' % below 1-month high';
  return { high1m: high, low1m: low, vs1m };
}
const held = checked.data.market;
const market = held ? {
  codesFrom: 'watchlist',
  codesAre: 'a watchlist, not holdings',
  lastClose: held.lastClose ? held.lastClose + ' (' + DateTime.fromISO(held.lastClose).setLocale('en').toFormat('cccc') + ')' : null,
  codes: held.holdings.map((h) => ({ symbol: h.symbol, name: h.name || undefined, changePct: h.pct,
    bigMove: Math.abs(h.pct) >= watch.marketThreshold, ...month(h.closes) })),
  notAvailable: (held.missing || []).map((m) => m.symbol + ': ' + m.reason),
} : null;

// Travel: Christmas round-trip fares. low7 is the lowest fare of the 7 days before today:
// Google's own history first, and our price log when Google gives none (CDG-HND).
const trip = checked.data.travel;
const travel = trip ? trip.routes.map((r) => {
  const h = r.history || [];
  // A copy searched before this change (11-01) stored plain fares ending with today; drop that last fare.
  const google = typeof h[0] === 'number' ? h.slice(0, -1).slice(-7) : h.filter((x) => x.day >= weekAgo && x.day < ctx.date).map((x) => x.price);
  const item = 'Flight CDG-' + r.code;
  const before = google.length ? google : logged(item);
  const low7 = before.length ? Math.min(...before) : null;
  return { city: r.city, code: r.code, fare: r.fare, low7, lowDays: before.length,
    lowFrom: google.length ? 'google' : before.length ? 'log' : null, vsLow7: vsLow(r.fare, low7), before,
    typicalRange: r.typical, hotelPerNight: ((trip.hotels || {})[r.code] || {}).perNight || null, priceLogItem: item };
}) : null;

const notConnected = checked.sources.filter((s) => s.status === 'off').map((s) => s.short);
const stale = checked.sources.filter((s) => s.status === 'stale').map((s) => s.short + ' (' + s.code + ')');

// "before" (the fares behind low7) is for the page's curve; the agent gets low7 and vsLow7 instead.
const candidates = { date: ctx.date, weekday: $now.setZone('Europe/Paris').setLocale('en').toFormat('cccc'), courses, mail, news: news.slice(0, 12), deals, market,
  travel: travel && travel.map(({ before, ...r }) => r), codex, notConnected, stale };
// The prompt is written by "Prepare agent input", after the Chinese and French texts are translated.
return [{ json: { candidates, courses, mail, hiddenMail, codesHidden, travel, quietKeywords, noDeal, codex } }];

// The page is in English (the user's rule, 11-01). The Chinese and French texts it will show are collected here:
// news titles, the Codex line, deal titles, mail subjects and class titles. Only these few go to the model.
// Mails with a one-time code were already left out by "Check sources and use cache".
const picked = $('Pick candidates').first().json;
const c = picked.candidates;
const foreign = (s) => /[㐀-鿿＀-￯]/.test(s) || /[àâçéèêëîïôûùüÿœæ]/i.test(s) ||
  /\b(le|la|les|des|du|au|aux|pour|avec|votre|vos|sur|une|et|est|pas|dans|par|nouveau|nouvelle|homme|femme|veste|noir|noire|blanc|taille|commande|cours|salle|examen|rappel|bienvenue)\b/i.test(s);
const strings = new Set();
const add = (s) => { if (typeof s === 'string' && s.trim() && foreign(s)) strings.add(s); };
for (const n of c.news || []) add(n.title);
add(c.codex);
for (const d of c.deals || []) add(d.title);
for (const m of c.mail || []) add(m.subject);
if (c.courses) {
  for (const x of c.courses.today || []) add(x.title);
  add(c.courses.next);
}
return [{ json: { strings: [...strings] } }];

// TEST ONLY. Stands in for the translation call, in its answer format (numbered lines, one per text).
// Chinese characters become "~", so the plumbing and the number check run without a model call.
const strings = $('Text to translate').first().json.strings;
return [{ json: { text: strings.map((s, k) => (k + 1) + '. [EN] ' + s.replace(/[㐀-鿿＀-￯]+/g, '~')).join('\n') } }];

// Each translation is checked before it is used: one numbered line per text, no Chinese left, and every number
// of the original still in it (Chinese amounts in 万/亿 and dates such as 12月 may change form).
// A text that fails keeps its original wording; a failed call keeps them all. The run never stops here.
const asked = $('Text to translate').first().json.strings;
const out = $('Translate to English').first().json || {};
const lines = {};
for (const l of String(out.text || '').split('\n')) {
  const m = l.match(/^\s*(\d+)[.)]\s+(.+?)\s*$/);
  if (m) lines[Number(m[1])] = m[2];
}
const digits = (s) => String(s).replace(/\D/g, '');
const map = {};
let kept = 0;
asked.forEach((orig, k) => {
  const t = lines[k + 1];
  const have = digits(t || '');
  const needed = [...String(orig).matchAll(/\d+(?:[.,]\d+)*(?=\s*([万亿千百月日号年时点分秒])?)/g)].filter((m) => !m[1]).map((m) => digits(m[0]));
  if (!t || /[㐀-鿿]/.test(t) || needed.some((n) => !have.includes(n))) { kept += 1; return; }
  map[orig] = t;
});
const error = out.error ? String(out.error.message || out.error).slice(0, 80) : null;
return [{ json: { map, summary: { asked: asked.length, translated: Object.keys(map).length, kept, error } } }];

// The agent and the page see English: the checked translations replace the Chinese and French texts that
// "Pick candidates" chose. The original wording is kept beside them (titleOriginal, subjectOriginal).
const ctx = $('Run context').first().json;
const picked = $('Pick candidates').first().json;
const ran = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
const tr = ran('English text') ? $('English text').first().json : { map: {}, summary: null };
const en = (s) => (typeof s === 'string' && tr.map[s]) || s;
const c = JSON.parse(JSON.stringify(picked.candidates));
c.news = (c.news || []).map((n) => (en(n.title) !== n.title ? { ...n, title: en(n.title), titleOriginal: n.title } : n));
c.deals = (c.deals || []).map((d) => (en(d.title) !== d.title ? { ...d, title: en(d.title), titleOriginal: d.title } : d));
if (c.mail) c.mail = c.mail.map((m) => (en(m.subject) !== m.subject ? { ...m, subject: en(m.subject), subjectOriginal: m.subject } : m));
if (c.courses) c.courses = { ...c.courses, today: (c.courses.today || []).map((x) => ({ ...x, title: en(x.title) })), next: en(c.courses.next) };
c.codex = en(c.codex);
// The agent gets only the English texts: an original beside them could end up as a pick's ref key.
// It does not get the deals: Today's five never comes from Deals (the user's rule, 11-02). The page still lists them.
const { deals, ...agentCandidates } = c;
const forAgent = JSON.stringify(agentCandidates, (k, v) => (k === 'titleOriginal' || k === 'subjectOriginal' ? undefined : v), 1);
const prompt = `Today is ${ctx.date} in Paris. Choose today's picks from these candidates.

Candidates (JSON):
${forAgent}`;
return [{ json: { ...picked, prompt, candidates: c, courses: c.courses, mail: c.mail, codex: c.codex, translation: tr.summary } }];

// Log today's best price per watchlist item, so get_price_history can compare across days.
const ctx = $('Run context').first().json;
// Flights are logged too ("Flight CDG-HND"), so the agent can compare a fare with earlier days.
const input = $('Prepare agent input').first().json;
// Only prices open to everyone are logged, so a member price never becomes the 7-day low.
return input.candidates.deals.filter((d) => d.publicPrice != null || !d.memberOnly)
  .map((d) => ({ json: { item: d.label, day: ctx.date, price: d.memberOnly ? d.publicPrice : d.price, source: d.memberOnly ? d.publicMerchant : d.merchant } }))
  .concat((input.travel || []).filter((r) => r.fare).map((r) => ({ json: { item: r.priceLogItem, day: ctx.date, price: r.fare, source: 'Google Flights' } })));

// TEST ONLY. Stands in for the editor agent while no model credential exists.
// It returns the same shape as the real agent, built from the real candidates, with no model call.
const c = $('Prepare agent input').first().json.candidates;
const picks = [];
for (const d of c.deals.filter((x) => x.underTarget && !x.memberOnly).slice(0, 2)) {
  picks.push({
    kind: 'act', title: d.label + ' at ' + d.price + ' €, ' + (d.vsLow7 || 'no 7-day low yet'), key: d.price + ' €',
    from: ['Deals'], ref: { block: 'deals', key: d.title }, tool: 'none',
    input: 'Dealabs: ' + d.title + ', ' + d.merchant + '.', why: 'Test fixture: no model call.',
    call: 'No tool call.', result: '—', decision: 'Test fixture.',
  });
}
for (const m of (c.mail || []).filter((x) => /confirm|book/i.test(x.subject)).slice(0, 1)) {
  picks.push({
    kind: 'act', title: m.subject, from: ['Mail'], ref: { block: 'mail', key: m.subject }, tool: 'none',
    input: 'Mail from ' + m.from + '.', why: 'Test fixture: no model call.', call: 'No tool call.', result: '—', decision: 'Test fixture.',
  });
}
for (const n of c.news.slice(0, 5 - picks.length)) {
  picks.push({
    kind: 'know', title: n.title, from: ['AI news'], ref: { block: 'ai', key: n.title }, tool: 'none',
    input: 'AIHOT: ' + n.title, why: 'Test fixture: no model call.', call: 'No tool call.', result: '—', decision: 'Test fixture.',
  });
}
// Mail: a plain keyword rule instead of the model's judgement.
const mail = (c.mail || []).map((m) => ({ id: m.id, need: /confirm|book|reply|pay|due/i.test(m.subject) ? 'act' : 'later' }));
return [{ json: { output: { picks, mail }, intermediateSteps: [] } }];

// TEST ONLY. A small Zeus-like ICS file around today's date, served at /webhook/zeus-fixture.
// The real build reads the user's own Zeus link from the private config table instead.
const day = (n) => $now.setZone('Europe/Paris').startOf('day').plus({ days: n });
const at = (n, hm) => day(n).set({ hour: Number(hm.slice(0, 2)), minute: Number(hm.slice(3)) }).toUTC().toFormat("yyyyMMdd'T'HHmmss'Z'");
const classes = [
  [0, '09:30', '12:30', 'Network Security', 'KB-412', 'GR1'],
  [0, '14:00', '17:00', 'Automation with n8n', 'KB-301', 'GR1'],
  [1, '09:00', '12:00', 'Project Management Principles', 'VJ-210', 'GR1'],
  [3, '13:30', '16:30', 'Business Management', 'KB-108', 'GR1'],
];
const lines = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Daily Page//Zeus fixture//EN'];
classes.forEach(([d, s, e, title, room, group], i) => lines.push(
  'BEGIN:VEVENT', 'UID:fixture-' + i, 'DTSTAMP:' + at(0, '00:00'), 'DTSTART:' + at(d, s), 'DTEND:' + at(d, e),
  'SUMMARY:' + title, 'LOCATION:' + room, 'DESCRIPTION:Group: ' + group, 'END:VEVENT'));
lines.push('END:VCALENDAR');
return [{ json: { ics: lines.join('\r\n') + '\r\n' } }];

// Build the EDITION object the page reads (fields: CONTRACT.md section 3).
const ctx = $('Run context').first().json;
const checked = $('Check sources and use cache').first().json;
const input = $('Prepare agent input').first().json;
const today = $("Load today's edition").first().json;
const agentRun = $('Editor agent').first().json;
const parsed = (agentRun.output && agentRun.output.picks) ? agentRun.output : ((agentRun.output || {}).output || {});

const previous = today && today.edition ? JSON.parse(today.edition) : null;
const version = (today && today.version ? Number(today.version) : 0) + 1;
const how = ctx.reason === 'page-open' ? 'opening the page after a missed 08:00 run'
  : ctx.trigger === 'rebuild' ? 'a manual rebuild' : 'the 08:00 schedule';
const now = $now.setZone('Europe/Paris').setLocale('en');

// The agent names the tool it used for each pick. "call" comes from the tool calls n8n actually ran,
// and a tool the agent names but never called is shown as no tool call.
// format_final_json_response is how n8n's output parser receives the answer, not a check, so it is left out.
const steps = (agentRun.intermediateSteps || [])
  .map((s) => ({ tool: (s.action || {}).tool, args: (s.action || {}).toolInput, used: false }))
  .filter((s) => s.tool !== 'format_final_json_response');
const argText = (a) => (a && typeof a === 'object' ? Object.values(a).filter((v) => typeof v !== 'object').join(' ') : String(a || ''));
const showCall = (s) => s.tool + '(' + JSON.stringify(s.args && typeof s.args === 'object' ? s.args : { input: s.args }) + ')';
const unverified = [];
const guarded = [];
const BLOCK_NAMES = { ai: 'AI news', deals: 'Deals', mail: 'Mail', market: 'Portfolio', travel: 'Travel' };
// The user's rule (11-02): Today's five never comes from Deals (it replaces the 11-01 rule "at most one deal, last").
// The agent does not see the deals, and a deal pick is still dropped here. The Deals block lists every deal as before.
const proposed = parsed.picks || [];
const isDeal = (p) => (p.ref || {}).block === 'deals';
const dealsLeftOut = proposed.filter(isDeal).length;
if (dealsLeftOut) {
  guarded.push('Rule applied: Today\'s five never comes from Deals; ' + dealsLeftOut + ' deal pick' + (dealsLeftOut > 1 ? 's' : '') +
    ' left out (still in the Deals block)');
}
const ordered = proposed.filter((p) => !isDeal(p)).slice(0, 5);
const picks = ordered.map((p) => {
  const claimed = p.tool && p.tool !== 'none' ? p.tool : null;
  const pick = {
    kind: p.kind === 'act' ? 'act' : 'know',
    title: p.title,
    // The page highlights key inside the title, so a key that is not in the title is dropped.
    key: p.key && String(p.title || '').includes(p.key) ? p.key : undefined,
    // Optional fields get defaults, so a short answer from the agent still renders.
    from: Array.isArray(p.from) && p.from.length ? p.from : [BLOCK_NAMES[(p.ref || {}).block]].filter(Boolean),
    ref: p.ref && p.ref.block ? p.ref : undefined,
    tool: claimed,
    input: p.input || p.title,
    why: p.why || p.decision || '',
    call: 'No tool call.',
    result: claimed ? p.result || 'Not stated.' : '—',
    decision: p.decision || p.why || '',
  };
  if (!claimed) return pick;
  // Only a call whose arguments appear in this pick counts (an item label, a keyword or a date).
  // A call of the same tool with other arguments is never borrowed for this pick.
  // A market pick also counts its company name: the agent searches news by name ("Interactive Brokers" for IBKR).
  const holding = ((checked.data.market || {}).holdings || []).find((h) => (p.ref || {}).block === 'market' &&
    h.symbol === String(p.ref.key || '').toUpperCase());
  const text = [p.title, p.input, p.ref && p.ref.key, holding && holding.name].join(' ').toLowerCase();
  const same = steps.filter((s) => s.tool === claimed && !s.used);
  // A call counts when its argument appears in the pick, or the pick's code appears in the argument ("Flight CDG-ZRH" for ZRH).
  const code = String((p.ref && p.ref.key) || '').toLowerCase();
  const match = same.find((s) => argText(s.args) && (text.includes(argText(s.args).toLowerCase()) ||
    (code.length >= 3 && argText(s.args).toLowerCase().includes(code))));
  if (match) {
    match.used = true;
    pick.call = showCall(match);
  } else {
    unverified.push('Editor agent named ' + claimed + ' for "' + p.title + '", but ' +
      (same.length ? 'it was called with other arguments' : 'never called it') + '; shown as no tool call');
    Object.assign(pick, { tool: null, call: 'No tool call.', result: '—' });
  }
  return pick;
});
const toolCalls = steps.length;

const c = input.candidates;
const watch = $('My watchlist').first().json;
// The page finds a pick's row by ref.key, so the key must be the row's exact title or code.
// The agent sometimes writes a short form ("AirPods" for a long Dealabs title); map it to the row.
const norm = (t) => String(t || '').toLowerCase().trim();
for (const pick of picks) {
  const ref = pick.ref;
  if (!ref) continue;
  const k = norm(ref.key);
  if (ref.block === 'ai') {
    const n = c.news.find((x) => norm(x.title) === k || norm(x.url) === k) || c.news.find((x) => k && norm(x.title).includes(k));
    if (n) ref.key = n.title;
  } else if (ref.block === 'mail') {
    const m = (input.mail || []).find((x) => norm(x.subject) === k) || (input.mail || []).find((x) => k && norm(x.subject).includes(k));
    if (m) ref.key = m.subject;
  } else if (ref.block === 'market' || ref.block === 'travel') {
    ref.key = String(ref.key || '').toUpperCase();
  }
}

// Picks the workflow makes itself, from candidates the agent did not pick. They are "know" and have no tool.
const taken = new Set(picks.filter((p) => p.ref).map((p) => p.ref.block + ':' + norm(p.ref.key)));
const codes = ((c.market || {}).codes || []).slice().sort((a, b) => Math.abs(b.changePct) - Math.abs(a.changePct));
const freshNews = (c.news || []).filter((n) => !taken.has('ai:' + norm(n.title)));
const made = (x, why) => {
  taken.add(x.block + ':' + norm(x.key));
  return { kind: 'know', title: x.title, key: undefined, from: [x.from], ref: { block: x.block, key: x.key }, tool: null,
    input: x.title, why, call: 'No tool call.', result: '—', decision: why };
};
const newsPick = (n) => ({ block: 'ai', key: n.title, from: 'AI news', title: n.title });
const marketPick = (m) => ({ block: 'market', key: m.symbol, from: 'Portfolio',
  title: m.symbol + ' ' + (m.changePct < 0 ? 'fell ' : 'rose ') + Math.abs(m.changePct) + ' % at the last close' + (m.vs1m ? ', ' + m.vs1m : '') });

// The user's rule (11-02): more AI news in the five, since there is big AI news most days. At least 2 AI news picks
// and at most 2 market picks: the weakest market pick that is not "act" (the smallest move) gives its place,
// in the same position, to the first AI news the agent did not pick.
const count = (block) => picks.filter((p) => (p.ref || {}).block === block).length;
const moveOf = (p) => Math.abs((codes.find((m) => m.symbol === p.ref.key) || {}).changePct || 0);
const swapped = [];
while ((count('ai') < 2 || count('market') > 2) && freshNews.length) {
  const weakest = picks.filter((p) => (p.ref || {}).block === 'market' && p.kind !== 'act').sort((a, b) => moveOf(a) - moveOf(b))[0];
  if (!weakest) break;
  picks[picks.indexOf(weakest)] = made(newsPick(freshNews.shift()),
    'Added by the workflow: Today\'s five has at least 2 AI news, so this took the place of ' + weakest.ref.key + '.');
  swapped.push(weakest.ref.key);
}
if (swapped.length) {
  guarded.push('Rule applied: at least 2 AI news and at most 2 market picks in Today\'s five; ' + swapped.join(', ') +
    (swapped.length > 1 ? ' were' : ' was') + ' replaced by AI news');
}

// Today's five is still five picks (the user's rule, 11-02). When the agent gives fewer, the workflow adds candidates
// it did not pick: the AI news in candidate order first, then the big market moves, then the other codes by size of move.
const added = [];
if (picks.length < 5) {
  const given = picks.length;
  const pool = freshNews.map(newsPick).concat(codes.filter((m) => m.bigMove).map(marketPick))
    .concat(codes.filter((m) => !m.bigMove).map(marketPick));
  for (const x of pool) {
    if (picks.length >= 5) break;
    if (taken.has(x.block + ':' + norm(x.key))) continue;
    picks.push(made(x, 'Added by the workflow: the agent gave ' + given + ' pick' + (given === 1 ? '' : 's') + ' and Today\'s five has 5.'));
    added.push(x.key);
  }
  if (added.length) {
    guarded.push('Rule applied: Today\'s five has 5 picks; the agent gave ' + given + ', so ' + added.length + ' ' +
      (added.length > 1 ? 'were' : 'was') + ' added from the candidates (' + added.join('; ') + ')');
  }
}

// Holdings or watchlist: the agent once called an IBKR holding "on a watchlist". The page data decides the word.
const held = checked.data.market;
if (held) {
  for (const pick of picks) {
    if (!(pick.ref && pick.ref.block === 'market') && !pick.from.includes('Portfolio')) continue;
    const wrong = held.codesFrom === 'ibkr' ? /watch\s?list/i : /\b(your|my)\s+(holdings?|portfolio|positions?|stocks?|shares?)\b/i;
    if (![pick.title, pick.why, pick.decision].some((t) => wrong.test(String(t || '')))) continue;
    const h = held.holdings.find((x) => x.symbol === String((pick.ref || {}).key || '').toUpperCase()) || held.holdings[0];
    const what = held.codesFrom === 'ibkr' ? 'one of your holdings (' + h.weightPct + ' % of the portfolio)' : 'on your watchlist (not a holding)';
    for (const f of ['title', 'why', 'decision']) {
      if (wrong.test(String(pick[f] || ''))) pick[f] = f === 'title' ? h.symbol + ' ' + (h.pct < 0 ? 'fell ' : 'rose ') + Math.abs(h.pct) + ' % at the last close' : h.symbol + ' is ' + what + '.';
    }
    guarded.push('Rule applied: ' + h.symbol + ' comes from ' + (held.codesFrom === 'ibkr' ? 'IBKR, so it is called a holding' : 'the watchlist, so it is not called a holding'));
  }
}

// A low from fewer than 7 days is an "N-day low" (the agent wrote "7-day low" for a 6-day low in execution 369).
const sevenDay = /\b(?:7|seven)[- ]day low\b/i;
for (const pick of picks) {
  const ref = pick.ref || {};
  const row = ref.block === 'travel' ? (input.travel || []).find((r) => r.code === ref.key) : null;
  if (!row || !(row.lowDays > 0 && row.lowDays < 7)) continue;
  const fields = ['title', 'why', 'decision'].filter((f) => sevenDay.test(String(pick[f] || '')));
  for (const f of fields) pick[f] = String(pick[f]).replace(new RegExp(sevenDay.source, 'gi'), row.lowDays + '-day low');
  if (fields.length) guarded.push('Rule applied: ' + row.code + ' has ' + row.lowDays + ' days of prices, so "7-day low" is written "' + row.lowDays + '-day low"');
}

// The page highlights key in the title. Claude Haiku 5.5 rarely gives one (none in executions 295–338),
// so a missing key is taken from the title: a price, a percent, the item's name, a date, then any number.
const inTitle = (title, word) => {
  const i = word ? title.toLowerCase().indexOf(String(word).toLowerCase()) : -1;
  return i < 0 ? null : title.slice(i, i + String(word).length);
};
let keysSet = 0;
for (const pick of picks) {
  if (pick.key && String(pick.title || '').includes(pick.key)) continue;
  const title = String(pick.title || '');
  const ref = pick.ref || {};
  const names = [ref.block === 'market' || ref.block === 'travel' ? ref.key : null]
    .concat(ref.block === 'ai' ? watch.newsKeywords || [] : []);
  const found = (title.match(/[€$£]\s?\d+(?:[.,]\d+)*|\d+(?:[.,]\d+)*\s?(?:€|EUR|USD)/) || [])[0] ||
    (title.match(/[+\-−]?\d+(?:[.,]\d+)?\s?%/) || [])[0] ||
    names.map((n) => inTitle(title, n)).find(Boolean) ||
    (title.match(/\b(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun)[a-z]*\.?\s+\d{1,2}(?:\s+[A-Z][a-z]{2,8})?|\b\d{1,2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*/) || [])[0] ||
    (title.match(/\d+(?:[.,]\d+)*/) || [])[0];
  if (found) {
    pick.key = found;
    keysSet += 1;
  }
}

// The agent sorts each mail into "act" (needs you soon) or "later". A mail it skipped counts as "later".
function mailBlock(mails, sorted, hidden) {
  const byId = {};
  for (const m of sorted) byId[m.id] = m;
  const act = [];
  const later = [];
  for (const m of mails) {
    const s = byId[m.id];
    if (s && s.need === 'act') act.push({ from: m.from, subject: m.subject, deadline: s.deadline || null, isNew: m.isNew });
    else later.push({ from: m.from, subject: m.subject, isNew: m.isNew });
  }
  return { act, later, hidden };
}
const blackFriday = $now.setZone('Europe/Paris').set({ year: 2026, month: 11, day: 27 }).startOf('day');
const edition = {
  mode: 'live',
  date: ctx.date,
  day: now.day,
  weekday: now.toFormat('cccc'),
  monthYear: now.toFormat('LLLL yyyy'),
  builtAt: ctx.time,
  demoNote: null,
  version,
  history: ((previous && previous.history) || []).concat([{ v: version, time: ctx.time, how }]),
  log: checked.log.concat([
    ...(input.translation && input.translation.asked ? [{ t: now.toFormat('HH:mm:ss'), msg: 'Translated to English: ' + input.translation.translated + ' of ' +
      input.translation.asked + ' texts' + (input.translation.error ? ' (call failed: ' + input.translation.error + ')' : '') +
      (input.translation.kept ? '; ' + input.translation.kept + ' kept in the original language (check failed)' : ''), ...(input.translation.kept ? { bad: true } : {}) }] : []),
    { t: now.toFormat('HH:mm:ss'), msg: 'Editor agent: ' + picks.length + ' picks' +
      (proposed.length > 5 ? ' (' + proposed.length + ' proposed, 5 kept)' : '') + ', ' + toolCalls + ' tool calls' +
      (keysSet ? '; highlight word taken from the title for ' + keysSet + ' pick' + (keysSet > 1 ? 's' : '') : '') },
    ...unverified.concat(guarded).map((msg) => ({ t: now.toFormat('HH:mm:ss'), msg, bad: true })),
    { t: now.toFormat('HH:mm:ss'), msg: 'Edition ' + ctx.date + (version > 1 ? ' replaced: v' + (version - 1) + ' to v' + version + ', still 1 row' : ' saved as a new row') },
  ]),
  sources: checked.sources,
  picks,
  courses: input.courses,
  // codesHidden: mails with a one-time code, only counted ("1 verification code hidden").
  mail: input.mail ? { ...mailBlock(input.mail, parsed.mail || [], input.hiddenMail), codesHidden: input.codesHidden || 0 } : null,
  // Portfolio on the page: codes, daily change in % and price candles. No quantities or amounts.
  market: checked.data.market ? {
    holdings: checked.data.market.holdings.map((h) => ({ symbol: h.symbol, name: h.name || null, pct: h.pct, closes: h.closes, ohlc: h.ohlc })),
    // A watchlist code Twelve Data gave no candles for, with the reason (the other codes are shown as usual).
    missing: checked.data.market.missing || [],
    threshold: watch.marketThreshold,
    event: null,
    // Always "watchlist" since 11-01: the codes come from My watchlist; the IBKR position is not shown.
    codesFrom: 'watchlist',
    // The trading day of the newest close (a Friday on a weekend), so the page does not say "today".
    lastClose: checked.data.market.lastClose || null,
  } : null,
  travel: checked.data.travel ? {
    dates: checked.data.travel.dates,
    routes: input.travel.map((r) => {
      return { city: r.city, code: r.code, fare: r.fare, low7: r.low7, lowDays: r.lowDays, lowFrom: r.lowFrom, hotel: r.hotelPerNight,
        // Up to 8 points: the days behind low7, then today's fare (the last point is today), so the low is on the curve.
        series: (r.before || []).concat([r.fare]).filter((n) => n != null) };
    }),
    quota: checked.data.travel.usage ? 'SerpApi this month: ' + checked.data.travel.usage.used + ' of ' + checked.data.travel.usage.of + ' searches.' : null,
  } : null,
  ai: checked.data.aihot ? {
    hotCount: (checked.data.aihot.hot || []).length,
    watch: c.news.slice(0, 8).map((n) => ({ title: n.title, titleOriginal: n.titleOriginal, heat: n.heat, list: n.list, url: n.url, isNew: n.isNew })),
    empty: input.quietKeywords.length ? input.quietKeywords.join(', ') + ': nothing in the last 24 hours.' : '',
    codex: input.codex,
  } : null,
  deals: checked.data.deals ? {
    daysToBlackFriday: Math.max(0, Math.ceil(blackFriday.diff(now.startOf('day'), 'days').days)),
    // low7 has only prices open to everyone, so a member-price row is compared through publicPrice (null: none today).
    rows: c.deals.map((d) => ({ item: d.title, label: d.label, merchant: d.merchant, price: d.price, target: d.target, memberOnly: d.memberOnly,
      publicPrice: d.publicPrice, low7: d.low7, lowDays: d.lowDays, listPrice: d.listPrice, from: d.from, note: d.note, link: d.link })),
    empty: input.noDeal.length ? input.noDeal.join(', ') + ': no price today in Dealabs or Google Shopping.' : '',
  } : null,
};

return [{ json: { date: ctx.date, version, updated_at: $now.toISO(), edition: JSON.stringify(edition) } }];

// The agent failed or chose nothing. Keep the last saved edition; never publish an empty page.
